    swish: () => air(0.18, 2200, 800, 0.28),                // quick move / close
    rise: () => tone(300, 780, 0.55, 'sine', 0.3),          // hold / charge
    fall: () => tone(720, 280, 0.32, 'sine', 0.26),         // release / cancel
